content.content:
  1	// ac-test: S-001/AC98 — the headers sized as headers (stage HD1; the approved header picture, docs/design/builds/headers-picture/,
  2	// images 1 to 8, with the owner's answers "Bigger titles too", B, "All dark", A, and "Keep that part small", A). The suite has no
  3	// browser (AC80's method), so the page is the sandbox's own code under the fake DOM, and the stylesheets the page loads
  4	// (style.css, then sandbox.css) are cascaded over what it drew (tests/desk/css-cascade.mjs): every screen and sheet from each
  5	// fixture — AC62's and AC81's (screen-text.mjs: Service-Desk at 3117150 from `service-desk/`, a made-up project with one item of
  6	// each kind, and a v2.5 project in `poom/`'s placeholder form), `md-extremes/` (sandbox-fixtures.mjs's five made-up projects),
  7	// Service-Desk with J12's built pull requests, and Plan's made-up estimates (wa-fixtures.mjs) — and the states the walk does not
  8	// reach on its own (glance-fixtures.mjs, qw1-fixtures.mjs and vt1-fixtures.mjs: Home with "Since you last looked", Waiting with
  9	// questions and with none, the Kicked back strip with cards, an opened phase with two runs, the value targets' sheet; all made
 10	// up, NOT real records), in dark (forced, and the phone's own) and light, at 360 and 414 px. Each role in AC98's table is
 11	// checked by selector: its computed size, weight and colour; the kept-small roles, each measured, unchanged; the tokens'
 12	// values unchanged; and the two headings' small part. The stage-8 guard's exception for HD1 is AC88's test's
 13	// (tests/desk/ac88-dark.test.mjs, `HD1_ONCE`); the Chromium captures at 360 × 740 and 414 × 896 are the pull request's.
 14	import test from 'node:test';
 15	import assert from 'node:assert/strict';
 16	import { readFileSync } from 'node:fs';
 17	import { join } from 'node:path';
 18	import { SRC, CONFIG } from './helpers.mjs';
 19	import { loadSandbox, findAll, byClass, openIdle } from './sandbox-helpers.mjs';
 20	import { NOW, extremes } from './sandbox-fixtures.mjs';
 21	import { textSetup } from './screen-text.mjs';
 22	import { SD3, sdRepo } from './tv2-fixtures.mjs';
 23	import { waSetup, WORKED, memStore } from './wa-fixtures.mjs';
 24	import { parseCss, treeOf, cascade, nodes } from './css-cascade.mjs';
 25	import { PF_ROWS } from '../../src/public/lib/portfolio.js';
 26	import { HOME_WORDS } from '../../src/lib/home.js';
 27	import { PAGE_WORDS } from '../../src/lib/projectpage.js';
 28	import { quietState, twoMixState, textState, gatesState, deviceMarks, KICKED, GATE4, GATE_KEY, MIX_PROJECT, SD, G7_OPENS, G8B_OPENS, G9_OPENS, lookedAt } from './glance-fixtures.mjs';
 29	import { QW1_OPENS } from './qw1-fixtures.mjs';
 30	import { VT1_OPENS } from './vt1-fixtures.mjs';
 31	import { POLL_MS } from '../../src/lib/scheduler.js';
 32	
 33	const SANDBOX_CSS = readFileSync(join(SRC, 'public', 'sandbox.css'), 'utf8');
 34	const JS = readFileSync(join(SRC, 'public', 'sandbox.js'), 'utf8');
 35	const RULES = (() => {
 36	  const a = parseCss(readFileSync(join(SRC, 'public', 'style.css'), 'utf8'), 'style.css');
 37	  const b = parseCss(SANDBOX_CSS, 'sandbox.css').map((r) => ({ ...r, order: r.order + a.length }));
 38	  return [...a, ...b];
 39	})();
 40	const FLAT = SANDBOX_CSS.replace(/\/\*[\s\S]*?\*\//g, '');
 41	const V2 = FLAT.slice(FLAT.indexOf('@font-face')); // mockup v2's block (AC62's and AC81's tests)
 42	const OLDER = FLAT.slice(0, FLAT.indexOf('@font-face'));
 43	const rule = (sel) => {
 44	  const re = new RegExp(`(?:^|})\\s*${sel.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s*\\{([^}]*)\\}`);
 45	  const m = re.exec(V2);
 46	  return m ? m[1] : '';
 47	};
 48	
 49	const INK = { light: { ink: '#18191c', ink2: '#5c5f66' }, dark: { ink: '#ecedef', ink2: '#a2a5ac' } };
 50	/** Dark forced on a light phone (the frames' way), the phone's own dark, and light; each at 360 and 414 px. */
 51	const WAYS = [
 52	  { name: 'dark (data-theme)', theme: 'dark', scheme: 'light', attr: 'dark' },
 53	  { name: 'dark (the phone)', theme: 'dark', scheme: 'dark', attr: null },
 54	  { name: 'light', theme: 'light', scheme: 'light', attr: null },
 55	].flatMap((w) => [360, 414].map((width) => ({ ...w, width, name: `${w.name}, ${width} px` })));
 56	
 57	const plain = (v) => String(v == null ? '' : v).replace(/⟦[^|⟧]*\|([^⟧]*)⟧/g, '$1').trim();
 58	const is = (n, tag, cls) => Boolean(n && n.tag === tag && (!cls || n.cls.has(cls)));
 59	const bare = (n) => n.cls.size === 0;
 60	const up = (n, pred) => { for (let a = n.parent; a; a = a.parent) if (pred(a)) return a; return null; };
 61	const SANS = /^"IBM Plex Sans"/;
 62	const MONO = /^"IBM Plex Mono"/;
 63	
 64	/**
 65	 * AC98's table, by selector, and its kept-small list: each role's match and its look ([size, weight, colour, family]), the
 66	 * colour a token's name. `null` leaves a part unchecked.
 67	 */
 68	const ROLES = [
 69	  // Screen and sheet titles (answer B).
 70	  ['a screen\'s title (.v2-title)', (n) => is(n, 'h1', 'v2-title'), ['28px', '600', 'ink', SANS], { lh: '33.6px' }],
 71	  ['Team\'s, a member\'s and a Details view\'s title (.sb-hdr h1)', (n) => is(n, 'h1') && Boolean(up(n, (a) => a.cls.has('sb-hdr'))), ['28px', '600', 'ink', SANS], { lh: '33.6px' }],
 72	  ['a sheet\'s title (.v2-stitle)', (n) => is(n, 'h2', 'v2-stitle'), ['20px', '600', 'ink', SANS], { lh: '26px' }],
 73	  ['a Team sheet\'s title (.sb-sheet-t)', (n) => n.cls.has('sb-sheet-t'), ['20px', '600', 'ink', SANS], { lh: '26px' }],
 74	  // Section and sheet-block heads, 600 15 px --ink (answer A).
 75	  ['a section head (.v2-shw)', (n) => n.cls.has('v2-shw'), ['15px', '600', 'ink', SANS]],
 76	  ['a section head\'s row (.v2-sh)', (n) => n.cls.has('v2-sh'), ['15px', '600', 'ink', SANS]],
 77	  ['a Plan group head (.v2-plhw)', (n) => n.cls.has('v2-plhw'), ['15px', '600', 'ink', SANS]],
 78	  ['a Home group\'s title (.v2-hgt)', (n) => n.cls.has('v2-hgt'), ['15px', '600', 'ink', SANS]],
 79	  ['"More detail" (.v2-mds)', (n) => n.cls.has('v2-mds'), ['15px', '600', 'ink', SANS]],
 80	  ['Waiting\'s section heads with cards (.v2-kh)', (n) => is(n, 'h2', 'v2-kh'), ['15px', '600', 'ink', SANS]],
 81	  ['a sheet\'s block head (.v2-bh)', (n) => n.cls.has('v2-bh'), ['15px', '600', 'ink', SANS]],
 82	  ['each target\'s name (.v2-vth)', (n) => is(n, 'h3', 'v2-vth'), ['15px', '600', 'ink', SANS]],
 83	  ['a Team or Details head (.sb-h2)', (n) => is(n, 'h2', 'sb-h2'), ['15px', '600', 'ink', SANS]],
 84	  ['a Team sheet\'s head (.sb-sec h3)', (n) => is(n, 'h3') && bare(n) && is(n.parent, 'div', 'sb-sec'), ['15px', '600', 'ink', SANS]],
 85	  // Sub-heads, 600 13 px, each keeping its colour.
 86	  ['a lane\'s head (.v2-lh)', (n) => is(n, 'h2', 'v2-lh'), ['13px', '600', 'ink', SANS]],
 87	  ['a project\'s name heading its group (.v2-gn)', (n) => n.cls.has('v2-gn'), ['13px', '600', 'ink', SANS]],
 88	  ['an opened phase\'s run head (.v2-runh)', (n) => n.cls.has('v2-runh'), ['13px', '600', 'ink', SANS]],
 89	  ['the Timeline\'s goal labels (.v2-goal .v2-label)', (n) => n.cls.has('v2-label') && Boolean(up(n, (a) => a.cls.has('v2-goal'))), ['13px', '600', 'ink2', SANS]],
 90	  ['Plan\'s card label (.v2-plcard > .v2-label)', (n) => n.cls.has('v2-label') && is(n.parent, 'section', 'v2-plcard'), ['13px', '600', 'ink2', SANS]],
 91	  ['"More detail"\'s sub-heads (.sb-h3)', (n) => n.cls.has('sb-h3') && Boolean(up(n, (a) => a.cls.has('v2-home') || a.cls.has('v2-proj'))), ['13px', '600', 'ink', SANS]],
 92	  // An opened phase's two group heads, one step under its run's head.
 93	  ['an opened phase\'s group head (.v2-subh)', (n) => n.cls.has('v2-subh'), ['12px', '600', 'ink', SANS]],
 94	  // An empty section's line, quieter than a full head; " · " and "none" in their mono.
 95	  ['an empty section\'s line (.v2-kq)', (n) => is(n, 'p', 'v2-kq'), ['13px', '500', 'ink2', SANS]],
 96	  ['its words (.v2-kl, .v2-kw)', (n) => (n.cls.has('v2-kl') || n.cls.has('v2-kw')) && is(n.parent, 'p', 'v2-kq'), ['13px', '500', 'ink2', SANS]],
 97	  ['its " · " and "none" (.v2-kn)', (n) => n.cls.has('v2-kn') && is(n.parent, 'p', 'v2-kq'), ['11px', '400', 'ink2', MONO]],
 98	  // The two headings' small part.
 99	  ['" · " and what follows (.v2-shs)', (n) => n.cls.has('v2-shs'), ['12px', '400', 'ink2', SANS]],
100	  ['the heading\'s time (.v2-shm)', (n) => n.cls.has('v2-shm'), ['12px', '400', 'ink2', MONO]],
101	  // Beside the heads, each keeping its own look.
102	  ['a head\'s mono note (.v2-sh .v2-mono)', (n) => n.cls.has('v2-mono') && n.parent && n.parent.cls.has('v2-sh'), ['11px', '400', 'ink2', MONO]],
103	  ['"Mark as seen" (.v2-seen)', (n) => n.cls.has('v2-seen'), ['11px', '500', 'ink', SANS]],
104	  ['a lane\'s or section\'s count (.v2-lc)', (n) => n.cls.has('v2-lc'), ['11px', '400', 'ink2', MONO]],
105	  ['a Home group\'s count (.v2-hgn)', (n) => n.cls.has('v2-hgn'), ['11px', '400', 'ink2', MONO]],
106	  ['a Home group\'s waiting part (.v2-hgy)', (n) => n.cls.has('v2-hgy'), ['11px', '500', 'ink', SANS]],
107	  ['"More detail"\'s chevron', (n) => is(n, 'svg') && is(n.parent, 'summary', 'v2-mds'), [null, null, 'ink2', null]],
108	  // Kept small, on purpose (as drawn, the picture approved, B).
109	  ['the Timeline\'s pinned band (.v2-tpn)', (n) => n.cls.has('v2-tpn'), ['12px', '600', 'ink', SANS]],
110	  ['the Timeline\'s compact title (.v2-tn)', (n) => n.cls.has('v2-tn'), ['15px', '600', 'ink', SANS]],
111	  ['Technical, Context and Why (.v2-bn)', (n) => n.cls.has('v2-bn'), ['11px', '500', 'ink2', SANS]],
112	  ['a card\'s kind label (.v2-kd)', (n) => n.cls.has('v2-kd'), ['11px', '500', 'ink2', SANS]],
113	  ['the board\'s buttons (.v2-step)', (n) => n.cls.has('v2-step'), ['11px', '500', null, SANS]],
114	  ['the folds (.v2-fold)', (n) => n.cls.has('v2-fold') && !n.cls.has('v2-untrb'), ['11px', '500', null, SANS]],
115	  ['a field label (.v2-label)', (n) => n.cls.has('v2-label') && !up(n, (a) => a.cls.has('v2-goal')) && !is(n.parent, 'section', 'v2-plcard'), ['11px', '500', 'ink2', SANS]],
116	  ['a tab (.v2-tab)', (n) => n.cls.has('v2-tab'), ['11px', '500', null, SANS]],
117	  ['the Now line (.v2-nowl)', (n) => n.cls.has('v2-nowl'), ['11px', '500', 'ink', MONO]],
118	  ['the small word over Team\'s title (.sb-eyebrow)', (n) => n.cls.has('sb-eyebrow') && Boolean(up(n, (a) => a.cls.has('sb-hdr'))), ['11px', '500', 'ink2', SANS]],
119	  ['a tile\'s name (.v2-tnm)', (n) => n.cls.has('v2-tnm'), ['13px', '600', null, SANS]],
120	  ['a phase row\'s name (.v2-sn)', (n) => n.cls.has('v2-sn'), ['13px', '500', null, SANS]],
121	  ['AC97\'s figure (.v2-vbig)', (n) => n.cls.has('v2-vbig'), ['24px', '600', 'ink', SANS]],
122	  ['the briefing\'s count (.v2-bt1)', (n) => n.cls.has('v2-bt1') && Boolean(up(n, (a) => a.cls.has('k-you'))), ['18px', '600', null, SANS]],
123	];
124	/** The heads that must turn dark: their words in --ink by the token, not a value of their own. */
125	const DARK_HEADS = ['.v2-shw', '.v2-sh', '.v2-hgt', '.v2-mds', '.v2-kh', '.v2-bh', '.v2-vth'];
126	
127	/** Each role's look on a screen, in every way; a failure once per role, way and look. */
128	function check(app, where, fails, met) {
129	  for (const way of WAYS) {
130	    const root = document.documentElement;
131	    const attrs = { ...(root.attrs || {}) };
132	    if (way.attr) attrs['data-theme'] = way.attr; else delete attrs['data-theme'];
133	    const tree = cascade(treeOf(app.view, { className: root.className, attrs }), RULES, { scheme: way.scheme, width: way.width, reducedMotion: false });
134	    const c = INK[way.theme];
135	    for (const n of nodes(tree)) {
136	      for (const [name, match, [size, weight, colour, family], extra] of ROLES) {
137	        if (!match(n)) continue;
138	        met.add(`${name} · ${way.name}`);
139	        const got = [plain(n.style.get('font-size')), plain(n.style.get('font-weight')), plain(n.style.get('color')).toLowerCase(), plain(n.style.get('font-family'))];
140	        const bad = [];
141	        if (size && got[0] !== size) bad.push(`size ${got[0]}, not ${size}`);
142	        if (weight && got[1] !== weight) bad.push(`weight ${got[1]}, not ${weight}`);
143	        if (colour && got[2] !== c[colour]) bad.push(`colour ${got[2]}, not --${colour} ${c[colour]}`);
144	        if (family && !family.test(got[3])) bad.push(`family ${got[3]}`);
145	        if (extra && extra.lh && plain(n.style.get('line-height')) !== extra.lh) bad.push(`line height ${plain(n.style.get('line-height'))}, not ${extra.lh}`);
146	        if (bad.length) {
147	          const k = `${name} · ${way.name} · ${bad.join(', ')}`;
148	          if (!fails.some((f) => f.endsWith(k))) fails.push(`${where} · "${String(n.text || '').trim().slice(0, 30)}" · ${k}`);
149	        }
150	      }
151	    }
152	  }
153	}
154	
155	async function opened(setup, hash = '#/', { now = NOW, store = null } = {}) {
156	  const app = await loadSandbox({ ...setup, hash, now, store });
157	  await app.advance(1000);
158	  await app.advance(61_000);
159	  return app;
160	}
161	const hrefsIn = (app, re) => {
162	  const out = [];
163	  const walk = (n) => { for (const c of n.children || []) { if (c.tag === 'a' && re.test(c.attrs.href || '') && !out.includes(c.attrs.href)) out.push(c.attrs.href); walk(c); } };
164	  walk(app.view);
165	  return out;
166	};
167	const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
168	
169	/** Every screen and sheet the fixture reaches, as AC88's walk opens them. */
170	async function everyScreen(app, projects, where, fails, met, counts) {
171	  const visit = async (hash) => {
172	    await app.go('#/');
173	    await app.go(hash);
174	    check(app, `${where} ${hash}`, fails, met);
175	    counts.screens++;
176	  };
177	  await visit('#/');
178	  await visit('#/since');
179	  for (const r of PF_ROWS) await visit(`#/pf/${r}`);
180	  await visit('#/waiting');
181	  for (const h of hrefsIn(app, /^#\/waiting\/card\//)) await visit(h);
182	  await visit('#/work');
183	  for (const h of hrefsIn(app, /^#\/work\/ms\//).slice(0, 3)) await visit(h);
184	  for (const p of projects) {
185	    const base = `#/p/${encodeURIComponent(p.name)}`;
186	    await visit(base);
187	    await visit(`#/waiting/${encodeURIComponent(p.name)}`);
188	    if (p.model === 'v3') for (const s of ['info', 'values', 'experiments', 'timeline', 'notes']) await visit(`${base}/${s}`);
189	    else await visit(`${base}/pipeline`);
190	    for (const s of ['asked', 'agents', 'team']) await visit(`${base}/${s}`);
191	    await app.go(`${base}/team`);
192	    if (findAll(app.view, (e) => e.dataset && e.dataset.k === 'team-idle').length) await openIdle(app);
193	    for (const m of hrefsIn(app, new RegExp(`^${esc(base)}/team/[^/]+$`))) {
194	      await visit(m);
195	      for (const s of hrefsIn(app, new RegExp(`^${esc(m)}/(now(/[^/]+)?|e/\\d+)$`)).slice(0, 2)) await visit(s);
196	    }
197	  }
198	}
