200	test('AC98 (the stylesheet): each role\'s rule by selector, in mockup v2\'s block — the titles 600 28 and 600 20 px at the tokens\' line heights, the section heads 600 15 px --ink, the sub-heads 600 13 px, an opened phase\'s group heads 600 12 px, the empty line --t-row --ink2, the small part --t-small --ink2 with its time in Plex Mono 400 12 px; the kept-small rules and every token\'s value unchanged; the older block holds none of them', () => {
201	  const want = [
202	    ['.v2-title', /font: 600 28px\/1\.2 var\(--font\)/],
203	    ['html.sb.v2-page .sb-hdr h1', /font: 600 28px\/1\.2 var\(--font\)/],
204	    ['.v2-stitle', /font: 600 20px\/1\.3 var\(--font\)/],
205	    ['html.sb.v2-page .sb-sheet-t', /font: 600 20px\/1\.3 var\(--font\)/],
206	    ['html.sb.v2-page .sb-h2, html.sb.v2-page .sb-sec h3', /font: 600 15px\/1\.3 var\(--font\); color: var\(--ink\)/],
207	    ['.v2-lh', /font: 600 13px\/1\.3 var\(--font\); color: var\(--ink\)/],
208	    ['.v2-kq', /font: var\(--t-row\); color: var\(--ink2\)/],
209	    ['.v2-gn', /font: 600 13px\/1\.3 var\(--font\); color: var\(--ink\)/],
210	    ['.v2-bh', /font: 600 15px\/1\.3 var\(--font\); color: var\(--ink\)/],
211	    ['.v2-shw', /font: 600 15px\/1\.3 var\(--font\); color: var\(--ink\)/],
212	    ['.v2-shs', /font: var\(--t-small\); color: var\(--ink2\)/],
213	    ['.v2-shm', /font: 400 12px\/1\.4 var\(--mono\)/],
214	    ['.v2-mds > .v2-k', /color: var\(--ink2\)/],
215	    ['html.sb .v2-home .sb-h3', /font: 600 13px\/1\.3 var\(--font\)/],
216	    ['html.sb .v2-proj .sb-h3', /font: 600 13px\/1\.3 var\(--font\)/],
217	    ['.v2-runh', /font: 600 13px\/1\.3 var\(--font\); color: var\(--ink\)/],
218	    ['.v2-subh', /font: 600 12px\/1\.3 var\(--font\); color: var\(--ink\)/],
219	    ['.v2-goal .v2-label', /font: 600 13px\/1\.3 var\(--font\); color: var\(--ink2\)/],
220	    ['.v2-plcard > .v2-label', /font: 600 13px\/1\.3 var\(--font\)/],
221	    ['.v2-vth', /font: 600 15px\/1\.3 var\(--font\); color: var\(--ink\)/],
222	    // Kept small.
223	    ['.v2-tpn', /font: 600 12px\/1\.3 var\(--font\)/],
224	    ['.v2-tn', /font: 600 15px\/1\.3 var\(--font\)/],
225	    ['.v2-bn', /font: var\(--t-label\); color: var\(--ink2\)/],
226	    ['.v2-kd', /font: var\(--t-label\); color: var\(--ink2\)/],
227	    ['.v2-label', /font: var\(--t-label\); color: var\(--ink2\)/],
228	    ['.v2-tab', /font: var\(--t-label\); color: var\(--ink2\)/],
229	    ['.v2-nowl', /font: 500 11px\/1\.4 var\(--mono\)/],
230	    ['.v2-tnm', /font: 600 13px\/1\.3 var\(--font\)/],
231	    ['.v2-sn', /font: var\(--t-row\)/],
232	    ['.v2-step.off', /color: var\(--ink2\)/],
233	    ['.v2-brief.k-you .v2-bt1', /font: var\(--t-sheet\)/],
234	  ];
235	  for (const [sel, re] of want) assert.match(rule(sel), re, sel);
236	  for (const sel of ['.v2-sh', '.v2-kh', '.v2-mds', '.v2-hgt']) assert.match(rule(sel), /font: 600 15px\/1\.3 var\(--font\);[^}]*color: var\(--ink\)|color: var\(--ink\);[^}]*font: 600 15px/, sel);
237	  assert.ok(/font: 600 15px\/1\.3 var\(--font\); color: var\(--ink\)/.test(rule('.v2-hgt')), '.v2-hgt');
238	  // Every head turned dark by the token, never a colour of its own.
239	  for (const sel of DARK_HEADS) assert.match(rule(sel), /color: var\(--ink\)/, `${sel} in --ink by the token`);
240	  // The folds and the board's buttons unchanged (--t-label).
241	  assert.equal((V2.match(/\.v2-fold \{[^}]*font: var\(--t-label\)/g) || []).length, 2, 'the folds\' two rules in --t-label');
242	  assert.match(V2, /\.v2-gatebtns \.v2-step \{[^}]*font: var\(--t-label\)/);
243	  // The tokens' values unchanged (AC81): AC97's figure 24 px by --t-title and the briefing's count 18 px by --t-sheet.
244	  const tok = Object.fromEntries([...FLAT.slice(FLAT.indexOf('html.sb .v2, html.sb.v2-page {')).matchAll(/(--t-[a-z]+): ([^;]+);/g)].slice(0, 9).map((m) => [m[1], m[2]]));
245	  assert.deepEqual(tok, {
246	    '--t-title': '600 24px/1.2 var(--font)', '--t-sheet': '600 18px/1.3 var(--font)', '--t-lead': '400 15px/1.45 var(--font)',
247	    '--t-row': '500 13px/1.35 var(--font)', '--t-body': '400 13px/1.45 var(--font)', '--t-small': '400 12px/1.4 var(--font)',
248	    '--t-label': '500 11px/1.35 var(--font)', '--t-mono': '400 11px/1.4 var(--mono)', '--t-input': '400 16px/1.4 var(--font)',
